package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaGradeSevenOrderingTest {
 @Test public void normalGradeSevenSupplyHasBothDirectionsAndPublicThreeNumberAnswers(){String pack="na-nied-primary-2024-v1",id="numberOrder";assertTrue(GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals(pack)).findFirst().orElseThrow().inGrade(id,7));var limits=GlobalCurriculum.limits(pack,id,7);assertEquals(1000000,limits.wholeMaximum(-1));assertEquals(0,limits.givenMinimum(-1));Generator g=new Generator(new Random(302));List<String> recent=new ArrayList<>();Set<Integer> modes=new HashSet<>();Checker checker=new Checker();for(int i=0;i<200;i++){Question q=g.next(id,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());double[] v=q.diagram.values;for(int j=0;j<3;j++)assertTrue(v[j]>=0&&v[j]<=1000000);modes.add((int)v[3]);int[] sorted=Arrays.stream(v).limit(3).mapToInt(n->(int)n).sorted().toArray();List<String> answer=new ArrayList<>();for(int j=0;j<3;j++)answer.add(""+sorted[v[3]==0?j:2-j]);q.answers=new String[]{"poison","poison","poison"};q.expression="poison";assertTrue(checker.check(q,List.of(),answer).correct());Collections.swap(answer,0,2);assertEquals(Checker.Status.WRONG_ANSWER,checker.check(q,List.of(),answer).status);assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertEquals(Set.of(0,1),modes);}
 @Test public void zeroAndOneMillionRemainPublicOrderingConditions(){for(int direction:new int[]{0,1}){Question q=PrimaryOrdering.make("numberOrder",new int[]{1000000,0,999999,direction});PrimaryOrdering.attach(q);q.answers=new String[]{"poison"};List<String> answer=direction==0?List.of("0","999999","1000000"):List.of("1000000","999999","0");assertTrue(new Checker().check(q,List.of(),answer).correct());assertEquals(3,HelpPlan.forQuestion(q).size());assertFalse(HelpPlan.forQuestion(q).canTransfer());}}
}
